  1	/**
  2	 * Clairic — typed values read out of text.
  3	 *
  4	 * Jev answers questions whose options we wrote down; Clairic reads values we
  5	 * did not enumerate: spans of the state, numbers, dates, durations, lists, and
  6	 * estimates or forecasts with an 80% interval (p10–p90). One parallel forward
  7	 * pass, no generated text, so a `text` answer is always a substring of the
  8	 * state it was given.
  9	 *
 10	 * Every scalar answer carries `p_null`, the probability the value is not in
 11	 * the input. Past `null_threshold` (default 0.5) `value` is null, but `guess`
 12	 * still holds the closest candidate — the near miss is data, not an error.
 13	 *
 14	 * Transport-free, like `system-one.ts`: `convex/extraction.ts` holds the
 15	 * credentials and talks to Not Organic's `POST /v1/extraction`.
 16	 */
 17	
 18	export type ExtractionFieldType =
 19	  | "text"
 20	  | "number"
 21	  | "date"
 22	  | "time"
 23	  | "datetime"
 24	  | "duration"
 25	  | "list"
 26	  | "estimate"
 27	  | "forecast";
 28	
 29	export type DurationUnit =
 30	  | "seconds"
 31	  | "minutes"
 32	  | "hours"
 33	  | "days"
 34	  | "weeks"
 35	  | "months"
 36	  | "years";
 37	
 38	export type ForecastInterval =
 39	  | "step"
 40	  | "minute"
 41	  | "hour"
 42	  | "day"
 43	  | "week"
 44	  | "month"
 45	  | "quarter"
 46	  | "year";
 47	
 48	export interface ExtractionField {
 49	  type: ExtractionFieldType;
 50	  instructions?: string;
 51	  unit?: string;
 52	  integer?: boolean;
 53	  decimals?: number;
 54	  items?: "text" | "number" | "date";
 55	  min?: number | string;
 56	  max?: number | string;
 57	  step?: number | "month" | "year";
 58	  scale?: "linear" | "log";
 59	  null_threshold?: number;
 60	  horizon?: number;
 61	  interval?: ForecastInterval;
 62	}
 63	
 64	export interface ExtractionRequest {
 65	  state?: string;
 66	  fields: Record<string, ExtractionField>;
 67	  /** ISO date anchoring relative dates and dates written without a year. */
 68	  reference_date?: string;
 69	  options?: { include_quantiles?: boolean; return_state_text?: boolean };
 70	}
 71	
 72	export interface ExtractionAnswer {
 73	  type: ExtractionFieldType;
 74	  value: unknown;
 75	  guess?: unknown;
 76	  p_null?: number;
 77	  confidence?: number;
 78	  unit?: string;
 79	  /** `text` answers: [start, end) into the state. */
 80	  span?: [number, number];
 81	  /** `list` answers: one span per item, in input order. */
 82	  spans?: [number, number][];
 83	  mean?: unknown;
 84	  median?: unknown;
 85	  p10?: unknown;
 86	  p90?: unknown;
 87	  p_below?: number;
 88	  p_above?: number;
 89	  quantiles?: unknown[];
 90	  steps?: unknown[];
 91	}
 92	
 93	export interface ExtractionUsage {
 94	  input_tokens: number;
 95	  output_tokens: number;
 96	  passes?: number;
 97	}
 98	
 99	export interface ExtractionResult {
100	  ok: boolean;
101	  model?: string;
102	  answers?: Record<string, ExtractionAnswer>;
103	  truncated?: boolean;
104	  usage?: ExtractionUsage;
105	  transport?: "notorganic" | "direct" | "none";
106	  error?: string;
107	  latencyMs?: number;
108	}
109	
110	/** Input tokens only, at the published Workers AI rate. */
111	export const USD_PER_INPUT_TOKEN = 0.1 / 1_000_000;
112	
113	/* ── Builders ──────────────────────────────────────────────────── */
114	
115	export const text = (instructions?: string): ExtractionField => ({
116	  type: "text",
117	  ...(instructions ? { instructions } : {}),
118	});
119	
120	export const list = (
121	  items: "text" | "number" | "date",
122	  instructions?: string,
123	): ExtractionField => ({
124	  type: "list",
125	  items,
126	  ...(instructions ? { instructions } : {}),
127	});
128	
129	export function estimate(
130	  instructions: string,
131	  range: { min: number; max: number; unit?: string; step?: number; log?: boolean },
132	): ExtractionField {
133	  return {
134	    type: "estimate",
135	    instructions,
136	    min: range.min,
137	    max: range.max,
138	    ...(range.unit ? { unit: range.unit } : {}),
139	    ...(range.step ? { step: range.step } : {}),
140	    ...(range.log ? { scale: "log" as const } : {}),
141	  };
142	}
143	
144	export function forecast(
145	  instructions: string,
146	  range: {
147	    min: number;
148	    max: number;
149	    horizon: number;
150	    interval: ForecastInterval;
151	    log?: boolean;
152	  },
153	): ExtractionField {
154	  return {
155	    type: "forecast",
156	    instructions,
157	    min: range.min,
158	    max: range.max,
159	    horizon: range.horizon,
160	    interval: range.interval,
161	    ...(range.log ? { scale: "log" as const } : {}),
162	  };
163	}
164	
165	/* ── Reading answers ───────────────────────────────────────────── */
166	
167	/** The exact substring a `text` answer points at, or null. */
168	export function spanText(
169	  state: string,
170	  answer: ExtractionAnswer | undefined,
171	): string | null {
172	  const span = answer?.span;
173	  if (!span || answer?.value === null) return null;
174	  return state.slice(span[0], span[1]);
175	}
176	
177	/** Every substring a `list` answer points at, in input order. */
178	export function spanTexts(
179	  state: string,
180	  answer: ExtractionAnswer | undefined,
181	): string[] {
182	  return (answer?.spans ?? []).map(([s, e]) => state.slice(s, e));
183	}
184	
185	/**
186	 * The closest candidate when the value is judged absent: `value` is null but
187	 * `guess` is not. For text answers the guess is still a span of the state.
188	 */
189	export function nearMiss(
190	  answer: ExtractionAnswer | undefined,
191	): { guess: unknown; pNull: number } | null {
192	  if (!answer || answer.value !== null || answer.guess == null) return null;
193	  return { guess: answer.guess, pNull: answer.p_null ?? 1 };
194	}
195	
196	export interface Interval {
197	  median: number;
198	  p10: number;
199	  p90: number;
200	}
201	
202	/** The numeric 80% interval of an estimate, or null for date estimates and gaps. */
203	export function interval(answer: ExtractionAnswer | undefined): Interval | null {
204	  const { median, p10, p90 } = answer ?? {};
205	  return typeof median === "number" &&
206	    typeof p10 === "number" &&
207	    typeof p90 === "number"
208	    ? { median, p10, p90 }
209	    : null;
210	}
211	
212	/** One interval per forecast step. */
213	export function forecastSteps(answer: ExtractionAnswer | undefined): Interval[] {
214	  if (!answer) return [];
215	  if (Array.isArray(answer.steps))
216	    return answer.steps
217	      .map((s) => interval(s as ExtractionAnswer))
218	      .filter((s): s is Interval => s !== null);
219	  const { median, p10, p90 } = answer;
220	  if (Array.isArray(median) && Array.isArray(p10) && Array.isArray(p90))
221	    return median.map((m, i) => ({
222	      median: m as number,
223	      p10: p10[i] as number,
224	      p90: p90[i] as number,
225	    }));
226	  const single = interval(answer);
227	  return single ? [single] : [];
228	}

 1	/** Shared pause-driven Clairic rate limit, parallel to the Jev budget. */
 2	const WINDOW_MS = 60_000;
 3	const MAX_PER_WINDOW = 4;
 4	const BACKOFF_MS = 30_000;
 5	export const MAX_RHYTHM_CALLS_PER_SESSION = 12;
 6	const calls: number[] = [];
 7	let backoffUntil = 0;
 8	let sessionCalls = 0;
 9	
10	export function extractionWait(now = Date.now()): number {
11	  while (calls.length && calls[0] <= now - WINDOW_MS) calls.shift();
12	  if (sessionCalls >= MAX_RHYTHM_CALLS_PER_SESSION) return Infinity;
13	  return Math.max(
14	    backoffUntil - now,
15	    calls.length >= MAX_PER_WINDOW ? calls[0] + WINDOW_MS - now : 0,
16	    0,
17	  );
18	}
19	export function spendExtraction(now = Date.now()): void {
20	  calls.push(now);
21	  sessionCalls++;
22	}
23	export function backOffExtraction(now = Date.now()): void {
24	  backoffUntil = now + BACKOFF_MS;
25	}
26	/** Back-off only, without the rhythm per-session cap, for other Clairic callers. */
27	export function extractionBackedOff(now = Date.now()): boolean {
28	  return backoffUntil > now;
29	}
30	export function __resetExtractionBudgetForTests(): void {
31	  calls.length = 0;
32	  backoffUntil = 0;
33	  sessionCalls = 0;
34	}

