    25	/** A near miss is returned as data; it never becomes an exact quote link. */
    26	export async function assistQuotation(
    27	  quote: string,
    28	  draft: string,
    29	  context: string,
    30	  research: PersonaResearch,
    31	): Promise<AssistedQuoteResolution> {
    32	  const literal = resolveQuotation(quote, draft, context);
    33	  if (literal.status === "resolved") return literal;
    34	  try {
    35	    if (literal.status === "unmatched" && research.extract) {
    36	      const window = selectPassageWindow(
    37	        draft,
    38	        `${quote} ${context}`,
    39	        24_000,
    40	        5,
    41	      );
    42	      if (!window.state || !research.reserve()) return literal;
    43	      const result = await research.extract({
    44	        state: window.state,
    45	        fields: {
    46	          passage: {
    47	            type: "text",
    48	            instructions: `The passage this note quotes or paraphrases: ${quote.slice(0, 1200)}. Note context: ${context.slice(0, 1600)}`,
    49	          },
    50	        },
    51	      });
    52	      const answer = result.ok ? result.answers?.passage : undefined;
    53	      const source = window.resolve(answer?.span);
    54	      if (!answer || !source) return literal;
    55	      if (answer.value === null) {
    56	        return answer.guess != null
    57	          ? { status: "near", ...source, pNull: answer.p_null ?? 1 }
    58	          : literal;
    59	      }
    60	      // The span only proposes text; the deterministic matcher still owns anchoring.
    61	      const checked = resolveQuotation(source.passage, draft, context);
    62	      return checked.status === "resolved" ? checked : literal;
    63	    }
    64	    if (literal.status === "ambiguous" && research.judge) {
    65	      const candidates = quotationCandidates(quote, draft);
    66	      // Do not silently omit an occurrence from a choice.
    67	      if (candidates.length < 2 || candidates.length > 8) return literal;
    68	      const paragraphs = manuscriptParagraphs(draft);
    69	      const options = candidates.map((_, i) => `occurrence_${i + 1}`);
    70	      const state = Object.fromEntries(
    71	        candidates.map((p, i) => [
    72	          options[i],
    73	          JSON.stringify({
    74	            ...p,
    75	            paragraph:
    76	              paragraphs.find(
    77	                (block) => p.from >= block.from && p.to <= block.to,
    78	              )?.passage ?? draft.slice(Math.max(0, p.from - 400), p.to + 400),
    79	          }),
    80	        ]),
    81	      );
    82	      if (Object.values(state).join("").length > 24_000 || !research.reserve())
    83	        return literal;
    84	      const result = await research.judge({
    85	        state: {
    86	          ...state,
    87	          note_context: context.slice(0, 2400),
    88	          quotation: quote.slice(0, 1200),
    89	        },
    90	        questions: {
    91	          occurrence: {
    92	            type: "choice",
    93	            instructions:
    94	              "Which occurrence does this note refer to, given its context and each occurrence's paragraph? Choose none when the context does not distinguish them.",
    95	            criteria: [...options, "none"],
    96	          },
    97	        },
    98	      });
    99	      const answer = result.ok
   100	        ? (result.answers?.occurrence as
   101	            | { probabilities?: Record<string, number> }
   102	            | undefined)
   103	        : undefined;
   104	      const probabilities = answer?.probabilities;
   105	      if (!probabilities) return literal;
   106	      const ranked = [...options, "none"]
   107	        .map((id) => ({ id, p: probabilities[id] }))
   108	        .sort((a, b) => b.p - a.p);
   109	      if (ranked.some((p) => !Number.isFinite(p.p) || p.p < 0 || p.p > 1))
   110	        return literal;
   111	      const [best, second] = ranked;
   112	      if (best.id === "none" || best.p < 0.85 || best.p - second.p < 0.25)
   113	        return literal;
   114	      return { status: "resolved", ...candidates[options.indexOf(best.id)] };
   115	    }
   116	  } catch {
   117	    // Keep the deterministic result on transport, budget or malformed-answer failure.
   118	  }
   119	  return literal;
   120	}
