   122	/** Mounted notes share in-flight work and completed results for one draft snapshot. */
   123	export function createGroundingAssistCache(maxEntries = 128) {
   124	  const cache = new Map<string, Promise<AssistedQuotation[]>>();
   125	  return async (
   126	    note: string,
   127	    draft: string,
   128	    research: PersonaResearch,
   129	  ): Promise<AssistedQuotation[]> => {
   130	    const bytes = new TextEncoder().encode(draft);
   131	    const hash = [
   132	      ...new Uint8Array(await crypto.subtle.digest("SHA-256", bytes)),
   133	    ]
   134	      .map((b) => b.toString(16).padStart(2, "0"))
   135	      .join("");
   136	    const key = `${hash}:${note}`;
   137	    const existing = cache.get(key);
   138	    if (existing) return existing;
   139	    const pending = (async () => {
   140	      const grounded = groundQuotations(note, draft);
   141	      const out: AssistedQuotation[] = [];
   142	      let attempted = 0;
   143	      for (const q of grounded) {
   144	        out.push({
   145	          ...q,
   146	          resolution:
   147	            q.resolution.status === "resolved" || attempted++ >= 4
   148	              ? q.resolution
   149	              : await assistQuotation(q.quote, draft, q.context, research),
   150	        });
   151	      }
   152	      return out;
   153	    })();
   154	    cache.set(key, pending);
   155	    while (cache.size > maxEntries) cache.delete(cache.keys().next().value!);
   156	    return pending;
   157	  };
   158	}
   159	
   160	export const assistGroundedNote = createGroundingAssistCache();
"}}}

