/* ── Public: run an agent client-side ───────────────────────────── */

export interface AdaptiveClientEditorialOptions {
  /** Review each private candidate; null means the judgement path is unavailable. */
  review: (candidate: {
    text: string;
    anchor?: string;
  }) => Promise<NoteVerdict | null>;
  maxReasoning?: EditorialReasoningLevel;
  maxAttempts?: number;
  onProgress?: (snapshot: EditorialDraftSnapshot) => void;
}

export async function runClientAgent(
  feature: AiFeature,
  req: AgentRequest,
  settings: AiSettings,
  onText?: StreamText,
  adaptive?: AdaptiveClientEditorialOptions,
  convexClient?: ConvexClient | null,
): Promise<AgentResponse | null> {
  const resolved = resolveFeatureConfigForPersona(
    settings,
    feature,
    req.persona,
  );
  if (!resolved) return null;

  const model = await createModel(resolved.provider, resolved.model);
  if (!model) return null;

  try {
    const system = buildSystemPrompt(req.persona);
    const fallbackType = defaultTypeForPersona(req.persona.id);
    // A persona can consult the writer's own knowledge bases while drafting a
    // note, but only from servers explicitly marked for it in Settings.
    const mcpTools = await loadMcpTools();
    const { clientPersonaResearch } = await import("./persona-research-client");
    const { mcpConvexClient } = await import("./mcp-research");
    const research = await clientPersonaResearch(
      convexClient ?? mcpConvexClient(),
      settings.judgement,
    );

    if (adaptive) {
      const result = await runAdaptiveEditorialDraft({
        operation: req.instruction,
        maxReasoning:
          adaptive.maxReasoning ??
          adaptiveReasoningCeiling(resolved.provider, resolved.model),
        maxAttempts: adaptive.maxAttempts,
        onProgress: adaptive.onProgress,
        generate: async ({ attempt, reasoning, repair }) => {
          const {
            tools: quoteTools,
            getAnchor,
            getAnchors,
            getExtractions,
          } = buildQuoteTools(req.draftText, research);
          let traceId: string | undefined;
          const text = await generateTrackedText({
            feature,
            resolved,
            model,
            system,
            prompt: buildUserPrompt({
              ...req,
              ...(repair.length ? { repairInstructions: [...repair] } : {}),
            }),
            spanName: `${feature}:draft-${attempt}`,
            evalSignals: {
              twyne_persona_id: req.persona.id,
              twyne_instruction: req.instruction ?? "feedback",
              twyne_draft_attempt: attempt,
              twyne_reasoning_level: reasoning,
            },
            tools: { ...quoteTools, ...mcpTools },
            onTrace: (nextTraceId) => {
              traceId = nextTraceId;
            },
            reasoningLevel: reasoning,
          });
          const cleaned = text.trim();
          if (!cleaned) throw new Error("empty-editorial-draft");
          const value: AgentResponse = {
            text: cleaned,
            type: classifyType(cleaned, fallbackType),
            provider: resolved.provider.type as AgentResponse["provider"],
            traceId,
            anchor: getAnchor(),
            anchors: getAnchors(),
            extractions: getExtractions(),
          };
          return { value, text: cleaned, anchor: value.anchor };
        },
        review: adaptive.review,
      });
      if (!result.candidate) return null;
      // Rejected attempts never reach the caller's stream. Only the selected
      // candidate is published after the review loop is complete.
      onText?.(textSnapshot(result.candidate.text));
      return result.candidate.value;
    }

    const user = buildUserPrompt(req);
    const {
      tools: quoteTools,
      getAnchor,
      getAnchors,
      getExtractions,
    } = buildQuoteTools(req.draftText, research);
    const tools = { ...quoteTools, ...mcpTools };
    let traceId: string | undefined;

    const text = await generateTrackedText({
      feature,
      resolved,
      model,
      system,
      prompt: user,
      spanName: feature,
      evalSignals: {
        twyne_persona_id: req.persona.id,
        twyne_instruction: req.instruction ?? "feedback",
      },
      tools,
      onText,
      onTrace: (nextTraceId) => {
        traceId = nextTraceId;
      },
    });

    const cleaned = text.trim();
    const anchor = getAnchor();
    // No usable text and no anchored quote — hand off to the deterministic
    // local generator, which carries its own anchor.
    if (!cleaned) {
      return generateLocalFeedback(req);
    }
    return {
      text: cleaned,
      type: classifyType(cleaned, fallbackType),
      provider: resolved.provider.type as AgentResponse["provider"],
      traceId,
      anchor,
      anchors: getAnchors(),
      extractions: getExtractions(),
    };
  } catch (err) {
    reportApplicationDiagnostic("twyne:ai-client:generate", err);
    return null;
  }
}

/* ── Public: room synthesis (combine the five memos) ────────────── */

export async function runClientRoomSynthesis(
  memos: MemoForSynthesis[],
  brief: ProjectBriefType | null,
  settings: AiSettings,
  writerProfile?: AgentRequest["writerProfile"],
  onText?: StreamText,
): Promise<{ text: string; provider: string } | null> {
  const resolved = resolveFeatureConfig(settings, "room-synthesis");
  if (!resolved) return null;
  const model = await createModel(resolved.provider, resolved.model);
  if (!model) return null;
  try {
    const text = await generateTrackedText({
      feature: "room-synthesis",
      resolved,
      model,
      system: buildSynthesisSystemPrompt(),
      prompt: buildSynthesisPrompt(memos, brief, writerProfile),
      spanName: "room_synthesis",
      evalSignals: { twyne_memo_count: memos.length },
      onText,
    });
    const cleaned = text.trim();
    return cleaned ? { text: cleaned, provider: resolved.provider.type } : null;
  } catch (err) {
    reportApplicationDiagnostic("twyne:ai-client:room-synthesis", err);
