 46	function fold(ch: string): string {
 47	  switch (ch) {
 48	    case "“":
 49	    case "”":
 50	    case "„":
 51	    case "«":
 52	    case "»":
 53	      return '"';
 54	    case "‘":
 55	    case "’":
 56	    case "‚":
 57	      return "'";
 58	    case "–":
 59	    case "—":
 60	    case "−":
 61	      return "-";
 62	    case " ":
 63	    case " ":
 64	    case " ":
 65	      return " ";
 66	    default: {
 67	      const lower = ch.toLowerCase();
 68	      return lower.length === 1 ? lower : ch;
 69	    }
 70	  }
 71	}
