 75	 * blank line (a block boundary) survives as "\n" so a quotation never matches
 76	 * across paragraphs.
 77	 */
 78	function normalise(source: string): Normalised {
 79	  let text = "";
 80	  const map: number[] = [];
 81	  let i = 0;
 82	  while (i < source.length) {
 83	    const ch = source[i];
 84	    if (/\s/.test(ch)) {
 85	      const start = i;
 86	      let breaks = 0;
 87	      while (i < source.length && /\s/.test(source[i])) {
 88	        if (source[i] === "\n") breaks++;
 89	        i++;
 90	      }
 91	      if (text.length === 0) continue;
 92	      text += breaks >= 2 ? "\n" : " ";
 93	      map.push(start);
 94	      continue;
 95	    }
 96	    if (ch === "." && source.startsWith("...", i)) {
 97	      text += "…";
 98	      map.push(i);
 99	      i += 3;
100	      continue;
101	    }
102	    text += fold(ch);
103	    map.push(i);
104	    i++;
105	  }
106	  return { text: text.replace(/[ \n]$/, ""), map };
107	}
