468	/** A synchronous freshness guard for reveal events; inference caching uses SHA-256. */
469	export function quotationDraftFingerprint(text: string): string {
470	  let a = 2166136261,
471	    b = 5381;
472	  for (let i = 0; i < text.length; i++) {
473	    a = Math.imul(a ^ text.charCodeAt(i), 16777619);
474	    b = Math.imul(b, 33) ^ text.charCodeAt(i);
475	  }
476	  return `${text.length}:${a >>> 0}:${b >>> 0}`;
477	}

