   136	  const push = (raw: string, index: number) => {
   137	    const quote = trimQuote(raw);
   138	    if (quote.length < MIN_CHARS) return;
   139	    if (quote.split(/\s+/).length < MIN_WORDS) return;
   140	    if (found.some((q) => q.quote === quote)) return;
   141	    const end = index + raw.length;
   142	    const context =
   143	      note.slice(Math.max(0, index - CONTEXT_CHARS), index) +
   144	      " " +
   145	      note.slice(end, end + CONTEXT_CHARS);
   146	    found.push({ quote, index, context });
   147	    taken.push([index, end]);
   148	  };
   149	
   150	  for (const line of note.matchAll(/^[ \t]*>[ \t]?(.+)$/gm)) {
   151	    const body = line[1];
   152	    push(body, (line.index ?? 0) + line[0].indexOf(body));
   153	  }
   154	
   155	  for (const [open, close] of PAIRS) {
   156	    let at = 0;
   157	    while (at < note.length) {
   158	      const start = note.indexOf(open, at);
   159	      if (start < 0) break;
   160	      // A straight or curly apostrophe inside a word is not an opening mark.
   161	      if (open === "‘" && /\p{L}/u.test(note[start - 1] ?? "")) {
   162	        at = start + 1;
   163	        continue;
   164	      }
   165	      let end = note.indexOf(close, start + 1);
   166	      // Skip apostrophes ("don’t") when looking for the closing single mark.
   167	      while (open === "‘" && end > 0 && /\p{L}/u.test(note[end + 1] ?? "")) {
   168	        end = note.indexOf(close, end + 1);
   169	      }
   170	      if (end < 0) break;
   171	      const raw = note.slice(start + 1, end);
   172	      if (!raw.includes("\n\n") && !overlaps(start, end + 1)) {
   173	        push(raw, start + 1);
   174	      }
   175	      at = end + 1;
   176	    }
   177	  }
   178	  return found.sort((a, b) => a.index - b.index);
   179	}
   180	
   181	function occurrences(haystack: string, needle: string): number[] {
   182	  const out: number[] = [];
   183	  if (!needle) return out;
   184	  let at = haystack.indexOf(needle);
   185	  while (at >= 0) {
   186	    out.push(at);
   187	    at = haystack.indexOf(needle, at + 1);
   188	  }
   189	  return out;
   190	}
   191	
   192	/** Normalised spans where every elided segment appears, in order, in one block. */
   193	function elidedSpans(doc: string, segments: string[]): Array<[number, number]> {
   194	  const spans: Array<[number, number]> = [];
   195	  for (const start of occurrences(doc, segments[0])) {
   196	    let cursor = start + segments[0].length;
   197	    let ok = true;
   198	    for (const segment of segments.slice(1)) {
   199	      const next = doc.indexOf(segment, cursor);
   200	      if (
   201	        next < 0 ||
   202	        next - start > ELISION_SPAN ||
   203	        doc.slice(cursor, next).includes("\n")
   204	      ) {
   205	        ok = false;
   206	        break;
   207	      }
   208	      cursor = next + segment.length;
   209	    }
   210	    if (ok) spans.push([start, cursor]);
   211	  }
   212	  return spans;
   213	}
   214	
   215	function matchingSpans(
   216	  needle: string,
   217	  doc: Normalised,
   218	): Array<[number, number]> {
   219	  let spans: Array<[number, number]> = occurrences(doc.text, needle)
   220	    .map((at): [number, number] => [at, at + needle.length])
   221	    .filter(([s, e]) => !doc.text.slice(s, e).includes("\n"));
   222	  if (spans.length === 0) {
   223	    const segments = needle
   224	      .split(/\s*(?:…|\[…\]|\[\.\.\.\])\s*/)
   225	      .map((s) => s.trim())
   226	      .filter((s) => s.length >= 3);
   227	    if (segments.length > 1) spans = elidedSpans(doc.text, segments);
   228	  }
   229	  return spans;
   230	}
   231	
   232	/** Enumerate all occurrences with exactly the same normalisation as the resolver. */
   233	export function quotationCandidates(
   234	  quote: string,
   235	  manuscript: string,
   236	): Array<{ from: number; to: number }> {
   237	  const needle = normalise(trimQuote(quote)).text;
   238	  if (!needle || !manuscript) return [];
   239	  const doc = normalise(manuscript);
   240	  return matchingSpans(needle, doc).map(([s, e]) => {
   241	    const last = doc.map[e - 1];
   242	    const width = doc.text[e - 1] === "…" && manuscript[last] === "." ? 3 : 1;
   243	    return { from: doc.map[s], to: last + width };
   244	  });
   245	}
   246	
   247	/**
   248	 * Find a quotation in the manuscript. Offsets are into `manuscript` as given.
   249	 * `context` is the note text around the quotation; it only ever breaks ties.
   250	 */
   251	export function resolveQuotation(
   252	  quote: string,
   253	  manuscript: string,
   254	  context = "",
   255	): QuoteResolution {
   256	  const needle = normalise(trimQuote(quote)).text;
   257	  if (!needle || !manuscript) return { status: "unmatched" };
   258	  const doc = normalise(manuscript);
   259	
   260	  const spans = matchingSpans(needle, doc);
   261	  if (spans.length === 0) return { status: "unmatched" };
   262	
   263	  const toOriginal = ([s, e]: [number, number]) => {
   264	    const last = doc.map[e - 1];
   265	    // An ellipsis folded from "..." spans three source characters.
   266	    const width = doc.text[e - 1] === "…" && manuscript[last] === "." ? 3 : 1;
   267	    return { from: doc.map[s], to: last + width };
   268	  };
   269	  if (spans.length === 1)
   270	    return { status: "resolved", ...toOriginal(spans[0]) };
   271	
   272	  const cues = new Set(words(context));
   273	  const quoted = new Set(words(needle));
   274	  for (const w of quoted) cues.delete(w);
   275	  if (cues.size === 0) return { status: "ambiguous", count: spans.length };
   276	  const scored = spans
   277	    .map((span) => {
   278	      // Only the occurrence's own paragraph counts as its surroundings.
   279	      const before = doc.text.slice(
   280	        Math.max(0, span[0] - MANUSCRIPT_WINDOW),
   281	        span[0],
   282	      );
   283	      const after = doc.text.slice(span[1], span[1] + MANUSCRIPT_WINDOW);
   284	      const window =
   285	        before.slice(before.lastIndexOf("\n") + 1) + " " + after.split("\n")[0];
   286	      const near = new Set(words(window));
   287	      let score = 0;
   288	      for (const w of cues) if (near.has(w)) score++;
   289	      return { span, score };
   290	    })
   291	    .sort((a, b) => b.score - a.score);
   292	  const [best, runnerUp] = scored;
   293	  if (best.score > runnerUp.score) {
   294	    return { status: "resolved", ...toOriginal(best.span) };
   295	  }
   296	  return { status: "ambiguous", count: spans.length };
   297	}
   298	
   299	export interface GroundedQuotation extends Quotation {
   300	  resolution: QuoteResolution;
   301	}
   302	
   303	export function groundQuotations(
   304	  note: string,
   305	  manuscript: string,
   306	): GroundedQuotation[] {
   307	  return extractQuotations(note).map((q) => ({
   308	    ...q,
   309	    resolution: resolveQuotation(q.quote, manuscript, q.context),
   310	  }));
   311	}
   312	
   313	/** A note rendered as Markdown, each quotation linked to its own passage. */
   314	export function renderGroundedMarkdown(
   315	  text: string,
   316	  manuscript: string,
   317	): string {
   318	  const html = renderMarkdown(text);
   319	  if (!manuscript) return html;
   320	  return linkQuotations(html, groundQuotations(text, manuscript), manuscript);
   321	}
   322	
   323	/** The live draft text, asked of the editor synchronously ("" on the server). */
   324	export function currentManuscript(): string {
   325	  if (typeof window === "undefined") return "";
   326	  let text = "";
   327	  const receive = (e: Event) => {
   328	    text = ((e as CustomEvent).detail as string) ?? "";
   329	  };
   330	  window.addEventListener("twyne:draft-text", receive);
   331	  window.dispatchEvent(new CustomEvent("twyne:request-draft"));
   332	  window.removeEventListener("twyne:draft-text", receive);
   333	  return text;
   334	}
   335	
   336	/** Window event a quote link sends; the editor resolves it again live. */
   337	export const REVEAL_QUOTE_EVENT = "twyne:reveal-quote";
   338	
   339	export interface RevealQuoteDetail {
   340	  quote: string;
   341	  context: string;
   342	  from?: number;
   343	  to?: number;
   344	  draftFingerprint?: string;
   345	}
   346	
   347	/** A choice can select one repeat only while its manuscript snapshot is current. */
   348	export function resolveQuotationForReveal(
   349	  quote: string,
   350	  manuscript: string,
   351	  context: string,
   352	  hint?: RevealQuoteDetail,
   353	): QuoteResolution {
   354	  if (
   355	    hint?.draftFingerprint === quotationDraftFingerprint(manuscript) &&
   356	    Number.isSafeInteger(hint.from) &&
   357	    Number.isSafeInteger(hint.to) &&
   358	    hint.from! >= 0 &&
   359	    hint.to! > hint.from! &&
   360	    hint.to! <= manuscript.length &&
   361	    manuscript.slice(hint.from, hint.to) === quote
   362	  )
   363	    return { status: "resolved", from: hint.from!, to: hint.to! };
   364	  return resolveQuotation(quote, manuscript, context);
   365	}
   366	
   367	function escapeHtml(value: string): string {
   368	  return value
   369	    .replace(/&/g, "&amp;")
   370	    .replace(/</g, "&lt;")
   371	    .replace(/>/g, "&gt;")
   372	    .replace(/"/g, "&quot;")
   373	    .replace(/'/g, "&#39;");
   374	}
   375	
   376	/** Replace the first occurrence of `needle` that sits in text, not in a tag. */
   377	function wrapInText(
   378	  html: string,
   379	  needle: string,
   380	  wrap: (inner: string) => string,
   381	): string {
   382	  let at = html.indexOf(needle);
   383	  while (at >= 0) {
   384	    const lastOpen = html.lastIndexOf("<", at);
   385	    const lastClose = html.lastIndexOf(">", at);
   386	    if (lastOpen <= lastClose) {
   387	      return html.slice(0, at) + wrap(needle) + html.slice(at + needle.length);
   388	    }
   389	    at = html.indexOf(needle, at + 1);
   390	  }
   391	  return html;
   392	}
   393	
   394	/**
   395	 * Mark each quotation in rendered note HTML: resolved ones become links to
   396	 * their passage, the rest say why they are not.
   397	 */
   398	export function linkQuotations(
   399	  html: string,
   400	  grounded: Array<
   401	    Omit<GroundedQuotation, "resolution"> & {
   402	      resolution:
   403	        | QuoteResolution
   404	        | {
   405	            status: "near";
   406	            passage: string;
   407	            from: number;
   408	            to: number;
   409	            pNull: number;
   410	          };
   411	    }
   412	  >,
   413	  manuscript = "",
   414	): string {
   415	  let out = html;
   416	  const fingerprint = quotationDraftFingerprint(manuscript);
   417	  for (const q of grounded) {
   418	    const needle = escapeHtml(q.quote);
   419	    const r = q.resolution;
   420	    if (r.status === "resolved") {
   421	      out = wrapInText(
   422	        out,
   423	        needle,
   424	        (inner) =>
   425	          `<span class="quote-link" role="link" tabindex="0" data-quote="${escapeHtml(manuscript ? manuscript.slice(r.from, r.to) : q.quote)}" data-draft-fingerprint="${fingerprint}" data-quote-from="${r.from}" data-quote-to="${r.to}" data-quote-context="${escapeHtml(q.context)}" title="Show this passage in the manuscript">${inner}</span>`,
   426	      );
   427	    } else {
   428	      const why =
   429	        r.status === "near"
   430	          ? `Closest passage, not quoted exactly: ${r.passage}`
   431	          : r.status === "ambiguous"
   432	            ? `These words appear ${r.count} times in the draft, and the note does not say which.`
   433	            : "Not in the draft as written. The passage may have changed since this note.";
   434	      out = wrapInText(
   435	        out,
   436	        needle,
   437	        (inner) =>
   438	          `<span class="quote-unresolved" title="${escapeHtml(why)}">${inner}</span>`,
   439	      );
   440	    }
   441	  }
   442	  return out;
   443	}
   444	
   445	/** Click (or Enter) on a quote link inside `event.target`'s note. */
   446	export function revealQuoteFromEvent(event: Event): boolean {
   447	  if (event instanceof KeyboardEvent && event.key !== "Enter") return false;
   448	  const el = (event.target as Element | null)?.closest?.<HTMLElement>(
   449	    ".quote-link[data-quote]",
   450	  );
   451	  if (!el) return false;
   452	  event.preventDefault();
   453	  event.stopPropagation();
   454	  window.dispatchEvent(
   455	    new CustomEvent<RevealQuoteDetail>(REVEAL_QUOTE_EVENT, {
   456	      detail: {
   457	        quote: el.dataset.quote ?? "",
   458	        context: el.dataset.quoteContext ?? "",
   459	        from: Number(el.dataset.quoteFrom),
   460	        to: Number(el.dataset.quoteTo),
   461	        draftFingerprint: el.dataset.draftFingerprint,
   462	      },
   463	    }),
   464	  );
   465	  return true;
   466	}
   467	
   468	/** A synchronous freshness guard for reveal events; inference caching uses SHA-256. */
   469	export function quotationDraftFingerprint(text: string): string {
   470	  let a = 2166136261,
   471	    b = 5381;
   472	  for (let i = 0; i < text.length; i++) {
   473	    a = Math.imul(a ^ text.charCodeAt(i), 16777619);
   474	    b = Math.imul(b, 33) ^ text.charCodeAt(i);
   475	  }
   476	  return `${text.length}:${a >>> 0}:${b >>> 0}`;
   477	}
"}}}

