  1	/**
  2	 * The quote tool the editorial personas call to pin a note to an exact
  3	 * passage from the draft.
  4	 *
  5	 * Instead of asking the model to retype a passage (which it paraphrases,
  6	 * truncates, or invents), we hand it a `quote_passage` tool: it passes the
  7	 * sentence it is responding to, and the tool fuzzy-resolves that against the
  8	 * actual draft and returns the *canonical* verbatim text. The resolved
  9	 * passage is captured as the note's anchor, so the anchor always comes from
 10	 * the draft itself rather than from the model's typing.
 11	 *
 12	 * Shared by both code paths:
 13	 *  - the client BYOK path in `src/utils/ai-client.ts`
 14	 *  - the Convex server path in `convex/agents.ts`
 15	 *
 16	 * Intentionally no `"use node";` directive and no zod dependency: this is
 17	 * pure string assembly plus the AI SDK's `tool`/`jsonSchema` helpers, so it
 18	 * bundles cleanly in the Vite client too.
 19	 */
 20	import { tool, jsonSchema, type ToolSet } from "ai";
 21	import {
 22	  selectPassageWindow,
 23	  type PassageRange,
 24	} from "../src/utils/passage-window";
 25	import {
 26	  validatePersonaFields,
 27	  validatePersonaQuestions,
 28	  type PersonaResearch,
 29	  type PersonaExtractionReading,
 30	  type PersonaExtractionAnswer,
 31	} from "../src/utils/persona-research";
 32	import type { ExtractionField } from "../src/utils/extraction";
 33	import type { JudgementQuestion } from "./lib/judgementContract";
 34	
 35	/* ── Draft passage resolution (verbatim + fuzzy match) ──────────── */
 36	
 37	/**
 38	 * Resolve a (possibly approximate) quote against the draft, returning the
 39	 * exact text as it appears in the draft, or undefined when it cannot be
 40	 * matched. Used to be `persona-anchors.extractDynamicFeedbackAnchor`'s
 41	 * inner matcher; now the single source of truth for both anchoring and the
 42	 * quote tool.
 43	 */
 44	export function resolveDraftPassage(
 45	  quote: string | undefined,
 46	  draftText: string,
 47	): string | undefined {
 48	  const cleaned = quote?.replace(/\s+/g, " ").trim();
 49	  if (!cleaned || cleaned.split(/\s+/).length < 3) return undefined;
 50	  if (draftText.includes(cleaned)) return cleaned;
 51	
 52	  const normalizedQuote = normalizeText(cleaned);
 53	  if (!normalizedQuote) return undefined;
 54	
 55	  for (const passage of draftPassages(draftText)) {
 56	    const normalizedPassage = normalizeText(passage);
 57	    if (
 58	      normalizedPassage === normalizedQuote ||
 59	      normalizedPassage.includes(normalizedQuote)
 60	    ) {
 61	      return passage;
 62	    }
 63	  }
 64	  return undefined;
 65	}
 66	
 67	/** Split a draft into candidate passages: each sentence and each paragraph. */
 68	export function draftPassages(draftText: string): string[] {
 69	  const passages: string[] = [];
 70	  for (const paragraph of draftText.split(/\n+/)) {
 71	    const trimmed = paragraph.trim();
 72	    if (!trimmed) continue;
 73	    const sentences = trimmed.match(/[^.!?]+[.!?]+(?=\s|$)/g) ?? [];
 74	    passages.push(...sentences.map((s) => s.trim()));
 75	    passages.push(trimmed);
 76	  }
 77	  return passages;
 78	}
 79	
 80	export function normalizeText(text: string): string {
 81	  return text
 82	    .toLowerCase()
 83	    .replace(/[“”]/g, '"')
 84	    .replace(/[‘’]/g, "'")
 85	    .replace(/[^a-z0-9'" ]+/g, " ")
 86	    .replace(/\s+/g, " ")
 87	    .trim();
 88	}
 89	
 90	/**
 91	 * The first substantive sentence of a draft — a deterministic anchor for the
 92	 * local fallback generator, which has no model and so cannot call the tool.
 93	 */
 94	export function firstSubstantiveSentence(
 95	  draftText: string,
 96	): string | undefined {
 97	  for (const passage of draftPassages(draftText)) {
 98	    if (passage.split(/\s+/).length >= 4) return passage;
 99	  }
100	  return undefined;
101	}
102	
103	/* ── The quote tool ─────────────────────────────────────────────── */
104	
105	export interface QuoteTools {
106	  /** Pass to `generateText({ tools })`. */
107	  tools: ToolSet;
108	  /** The first passage the model successfully quoted, used as the anchor. */
109	  getAnchor: () => string | undefined;
110	  getAnchors: () => string[];
111	  getExtractions: () => PersonaExtractionReading[];
112	}
113	
114	/**
115	 * Build a `quote_passage` tool bound to one draft. The execute closure records
116	 * every resolved passage so the caller can read back the anchor after
117	 * generation completes.
118	 */
119	export function buildQuoteTools(
120	  draftText: string,
121	  research?: PersonaResearch,
122	): QuoteTools {
123	  const resolved: string[] = [];
124	  const extractions: PersonaExtractionReading[] = [];
125	  const capture = (passage: string) => {
126	    if (!resolved.includes(passage) && resolved.length < 24)
127	      resolved.push(passage);
128	  };
129	  const safe = async (run: () => Promise<unknown>) => {
130	    try {
131	      return await run();
132	    } catch {
133	      return {
134	        ok: false,
135	        error:
136	          "Research unavailable or invalid arguments. Continue with the passages already found.",
137	      };
138	    }
139	  };
140	
141	  const tools: ToolSet = {
142	    quote_passage: tool({
143	      description:
144	        "Look up the exact text of a passage from the writer's draft. " +
145	        "Pass the sentence (or a close approximation of it) you are " +
146	        "responding to; the tool returns the verbatim text as it appears " +
147	        "in the draft. Call this before making any claim about the draft so " +
148	        "your note pins to the real passage. Do not retype passages by hand.",
149	      inputSchema: jsonSchema<{ query: string }>({
150	        type: "object",
151	        properties: {
152	          query: {
153	            type: "string",
154	            description:
155	              "The sentence or short passage from the draft you want to quote.",
156	          },
157	        },
158	        required: ["query"],
159	        additionalProperties: false,
160	      }),
161	      execute: async ({ query }) => {
162	        const passage =
163	          typeof query === "string"
164	            ? resolveDraftPassage(query, draftText)
165	            : undefined;
166	        if (passage) {
167	          capture(passage);
168	          return { found: true, passage };
169	        }
170	        return {
171	          found: false,
172	          passage: null,
173	          note: "No matching passage found in the draft. Quote something the writer actually wrote.",
174	        };
175	      },
176	    }),
177	  };
178	
179	  if (research?.extract) {
180	    tools.find_passages = tool({
181	      description:
182	        "Find verbatim draft passages about a topic before claiming a pattern. Returns source offsets and records several anchors. A selected window is partial coverage of a long manuscript.",
183	      inputSchema: jsonSchema<{ about: string; max?: number }>({
184	        type: "object",
185	        properties: {
186	          about: { type: "string", minLength: 1, maxLength: 1200 },
187	          max: { type: "integer", minimum: 1, maximum: 8 },
188	        },
189	        required: ["about"],
190	        additionalProperties: false,
191	      }),
192	      execute: async ({ about, max }) =>
193	        safe(async () => {
194	          if (typeof about !== "string" || !about.trim())
195	            return { ok: false, error: "Supply a topic." };
196	          const limit =
197	            typeof max === "number" && Number.isFinite(max)
198	              ? Math.max(1, Math.min(8, Math.floor(max)))
199	              : 4;
200	          const window = selectPassageWindow(draftText, about.slice(0, 1200));
201	          if (!research.reserve())
202	            return {
203	              ok: false,
204	              error: "Research budget reached. Finish the note.",
205	            };
206	          const result = await research.extract!({
207	            state: window.state,
208	            fields: {
209	              passages: {
210	                type: "list",
211	                items: "text",
212	                instructions: `Up to ${limit} passages about: ${about.slice(0, 1200)}`,
213	              },
214	            },
215	          });
216	          if (!result.ok)
217	            return { ok: false, error: "Passage search unavailable." };
218	          const answer = result.answers?.passages;
219	          const passages =
220	            answer?.value == null
221	              ? []
222	              : (answer.spans ?? [])
223	                  .slice(0, limit)
224	                  .map((span) => window.resolve(span))
225	                  .filter((p): p is PassageRange => p !== null);
226	          passages.forEach((p) => capture(p.passage));
227	          return {
228	            ok: true,
229	            passages,
230	            partial: window.truncated || !!result.truncated,
231	          };
232	        }),
233	    });
