 1	export interface PassageRange {
 2	  from: number;
 3	  to: number;
 4	  passage: string;
 5	}
 6	
 7	export function manuscriptParagraphs(draft: string): PassageRange[] {
 8	  const out: PassageRange[] = [];
 9	  for (const match of draft.matchAll(/[^\n]+/g)) {
10	    const from = match.index!;
11	    // Bound even a manuscript written as one paragraph.
12	    for (let offset = 0; offset < match[0].length; offset += 8000) {
13	      const start = from + offset;
14	      const to = Math.min(start + 8000, from + match[0].length);
15	      if (draft.slice(start, to).trim())
16	        out.push({ from: start, to, passage: draft.slice(start, to) });
17	    }
18	  }
19	  return out;
20	}
21	
22	export function selectPassageWindow(
23	  draft: string,
24	  query: string,
25	  limit = 96_000,
26	  max = Infinity,
27	) {
28	  const terms = new Set(query.toLowerCase().match(/[\p{L}\p{N}]{3,}/gu) ?? []);
29	  const ranked = manuscriptParagraphs(draft)
30	    .map((p) => {
31	      const words = new Set(
32	        p.passage.toLowerCase().match(/[\p{L}\p{N}]{3,}/gu) ?? [],
33	      );
34	      return {
35	        ...p,
36	        score: [...terms].filter((word) => words.has(word)).length,
37	      };
38	    })
39	    .sort((a, b) => b.score - a.score || a.from - b.from);
40	  const selected: PassageRange[] = [];
41	  let size = 0;
42	  for (const p of ranked) {
43	    if (selected.length >= max) break;
44	    if (size + p.passage.length + 2 > limit) continue;
45	    selected.push(p);
46	    size += p.passage.length + 2;
47	  }
48	  selected.sort((a, b) => a.from - b.from);
49	  let state = "";
50	  const segments = selected.map((p) => {
51	    const start = state.length;
52	    state += p.passage + "\n\n";
53	    return { ...p, start, end: state.length - 2 };
54	  });
55	  return {
56	    state: state.slice(0, -2),
57	    truncated: selected.length < ranked.length,
58	    resolve(span: unknown): PassageRange | null {
59	      if (!Array.isArray(span) || span.length !== 2) return null;
60	      const [s, e] = span;
61	      if (
62	        !Number.isSafeInteger(s) ||
63	        !Number.isSafeInteger(e) ||
64	        s < 0 ||
65	        e <= s
66	      )
67	        return null;
68	      const segment = segments.find((p) => s >= p.start && e <= p.end);
69	      if (!segment) return null;
70	      const from = segment.from + s - segment.start;
71	      const to = segment.from + e - segment.start;
72	      return { from, to, passage: draft.slice(from, to) };
73	    },
74	  };
75	}

