     7	export function manuscriptParagraphs(draft: string): PassageRange[] {
     8	  const out: PassageRange[] = [];
     9	  for (const match of draft.matchAll(/[^\n]+/g)) {
    10	    const from = match.index!;
    11	    // Bound even a manuscript written as one paragraph.
    12	    for (let offset = 0; offset < match[0].length; offset += 8000) {
    13	      const start = from + offset;
    14	      const to = Math.min(start + 8000, from + match[0].length);
    15	      if (draft.slice(start, to).trim())
    16	        out.push({ from: start, to, passage: draft.slice(start, to) });
    17	    }
    18	  }
    19	  return out;
    20	}
