    25	  limit = 96_000,
    26	  max = Infinity,
    27	) {
    28	  const terms = new Set(query.toLowerCase().match(/[\p{L}\p{N}]{3,}/gu) ?? []);
    29	  const ranked = manuscriptParagraphs(draft)
    30	    .map((p) => {
    31	      const words = new Set(
    32	        p.passage.toLowerCase().match(/[\p{L}\p{N}]{3,}/gu) ?? [],
    33	      );
