    35	        ...p,
    36	        score: [...terms].filter((word) => words.has(word)).length,
    37	      };
    38	    })
    39	    .sort((a, b) => b.score - a.score || a.from - b.from);
    40	  const selected: PassageRange[] = [];
    41	  let size = 0;
    42	  for (const p of ranked) {
    43	    if (selected.length >= max) break;
    44	    if (size + p.passage.length + 2 > limit) continue;
    45	    selected.push(p);
    46	    size += p.passage.length + 2;
    47	  }
    48	  selected.sort((a, b) => a.from - b.from);
    49	  let state = "";
    50	  const segments = selected.map((p) => {
    51	    const start = state.length;
    52	    state += p.passage + "\n\n";
