     2	 * One request budget for every System One caller that runs on a typing pause.
     3	 *
     4	 * Quick review and the in-flow tools both fire on pauses in the same editor.
     5	 * Separate limits would let the pair spend twice the rate either was sized
     6	 * for; one shared window keeps them honest with each other.
     7	 */
     8	const WINDOW_MS = 60_000;
     9	const MAX_PER_WINDOW = 12;
    10	const BACKOFF_MS = 30_000;
    11	
    12	const calls: number[] = [];
    13	let backoffUntil = 0;
    14	
    15	/** Milliseconds to wait before a call is allowed; 0 means go now. */
    16	export function systemOneWait(now = Date.now()): number {
    17	  while (calls.length && calls[0] <= now - WINDOW_MS) calls.shift();
    18	  return Math.max(
    19	    backoffUntil - now,
    20	    calls.length >= MAX_PER_WINDOW ? calls[0] + WINDOW_MS - now : 0,
    21	    0,
    22	  );
    23	}
    24	
    25	/** Record a call that is about to be made. */
    26	export function spendSystemOne(now = Date.now()): void {
    27	  calls.push(now);
    28	}
    29	
    30	/** A failed call quiets every pause-driven caller for a while. */
    31	export function backOffSystemOne(now = Date.now()): void {
    32	  backoffUntil = now + BACKOFF_MS;
    33	}
    34	
    35	export function __resetSystemOneBudgetForTests(): void {
    36	  calls.length = 0;
    37	  backoffUntil = 0;
    38	}
"}}}

