 78	): EntityInstrumentIndex {
 79	  let bytes = 0;
 80	  const blocks = segments.blocks.filter((block) => {
 81	    bytes += new TextEncoder().encode(block.text).byteLength;
 82	    return bytes <= 80_000;
 83	  });
 84	  const groups = analyzeNaming(blocks).groups;
 85	  const candidates: EntityCandidate[] = groups.slice(0, 60).map((group) => ({
 86	    id: `entity:${encodeURIComponent(group.canonical)}`,
 87	    name: group.canonical,
 88	    variants: group.variants,
 89	    mentions: group.mentions,
 90	    counts: segments.sections.map(
 91	      (section) =>
 92	        group.mentions.filter((mention) => mention.section === section.index)
 93	          .length,
 94	    ),
 95	  }));
 96	  const evidence: EntityEvidence[] = [];
 97	  let limited =
 98	    blocks.length < segments.blocks.length || groups.length > candidates.length;
 99	  for (const block of blocks) {
100	    if (block.kind !== "paragraph" && block.kind !== "quote") continue;
101	    const entityIds = candidates
102	      .filter((candidate) =>
103	        candidate.mentions.some(
104	          (mention) => mention.paragraph === block.paragraph,
105	        ),
106	      )
107	      .map((candidate) => candidate.id);
108	    if (entityIds.length)
109	      evidence.push({
110	        ...occurrence(block, 0, block.text.length, "entity-passage", {
111	          flagged: false,
112	        }),
113	        kind: "passage",
114	        entityIds,
115	      });
116	    // Double quotes only; apostrophes and unmatched quotation marks are not dialogue spans.
117	    for (const match of block.text.matchAll(/“([^”\n]+)”|"([^"\n]+)"/g)) {
118	      evidence.push({
119	        ...occurrence(
120	          block,
121	          match.index! + 1,
122	          match[0].length - 2,
123	          "entity-dialogue",
124	          { flagged: false },
125	        ),
126	        kind: "dialogue",
127	        entityIds,
128	      });
129	    }
130	    if (evidence.length > 240) {
131	      evidence.length = 240;
132	      limited = true;
133	      break;
134	    }
135	  }
136	  const sections = structuredClone(segments.sections);
137	  // Exact serialized source is retained for freshness; fingerprints are display aids only.
138	  const key = JSON.stringify([
139	    "entity-index-v1",
140	    blocks,
141	    sections,
142	    candidates,
143	    evidence,
144	  ]);
145	  return { key, candidates, evidence, sections, limited };
146	}
